/**
 * Centralized imagery. Every photo is generated by `npm run images` from
 * `images-src/` into SEO-named, responsive WebP variants (640/1280/1920w) plus
 * a 1600w JPEG used for social previews and structured data.
 */

export interface ImageAsset {
  /** Default src — the 1280w WebP. */
  src: string;
  srcSet: string;
  /** JPEG fallback, used for og:image and schema `image`. */
  jpg: string;
  /** Intrinsic ratio, set on <img> so the browser can reserve space. */
  width: number;
  height: number;
  alt: string;
  title: string;
}

export interface GalleryImage extends ImageAsset {
  id: string;
  category: string;
  span?: string;
}

function photo(
  name: string,
  width: number,
  height: number,
  alt: string,
  title: string,
  maxWidth = 1920
): ImageAsset {
  const widths = [640, 1280, 1920].filter((w) => w <= maxWidth);
  return {
    src: `/images/${name}-1280.webp`,
    srcSet: widths.map((w) => `/images/${name}-${w}.webp ${w}w`).join(', '),
    jpg: `/images/${name}.jpg`,
    width,
    height,
    alt,
    title
  };
}

